SELECT CASE WHEN stores.sqft >= 14449 THEN 'high' WHEN stores.sqft >= 6079 THEN 'mid' ELSE 'low' END sqft_bucket, COUNT(*) inventory_count, SUM(inventory.quantity) total_quantity FROM inventory RIGHT OUTER JOIN stores ON inventory.store_id = stores.id WHERE stores.city = 'Bangkok' GROUP BY CASE WHEN stores.sqft >= 14449 THEN 'high' WHEN stores.sqft >= 6079 THEN 'mid' ELSE 'low' END ORDER BY inventory_count DESC;
